function formatPrice(cents) {
  return `$${(cents / 100).toFixed(2)}`;
}

const total = formatPrice(1999);   // "$19.99" ✓
const bug = formatPrice("1999");   // "$1999.00"... wait, "1999"/100 = 19.99 → "$19.99"? No —
// "1999" / 100 is 19.99 (string coerced), but "19" / 100 would be 0.19
// and "abc" / 100 is NaN → "$NaN". The bug hides until runtime.

function formatPrice(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

formatPrice("1999");
// Error: Argument of type 'string' is not assignable to parameter of type 'number'.

// What you write (input.ts)
const name: string = "Ada";
function double(x: number): number { return x * 2; }

// What tsc emits (input.js) — types erased, logic identical
const name = "Ada";
function double(x) { return x * 2; }

// greet.ts
function greet(name: string): string {
  return `Hello, ${name.toUpperCase()}`;
}

greet("Ada");
greet(42);        // ← the compiler will reject this line
greet();          // ← and this one

// tsconfig.json (the parts that matter most)
{
  "compilerOptions": {
    "strict": true,          // noImplicitAny + strictNullChecks + friends
    "target": "ES2022",     // which JS version to emit
    "outDir": "./dist",     // where compiled JS goes
    "noEmit": true           // type-check only (bundler handles output)
  }
}

